from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    stack, result = [], []
    for char in paren_string.replace(' ', ''):
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                raise ValueError("Unmatched closing parenthesis")
            stack.pop()
            if not stack:
                result.append("".join(stack))
    return result
