def max_value_on_paths(N, grid_values):
    rows, cols = N, N
    dp = [[0]*cols for _ in range(rows)]
    path_values = [[0]*cols for _ in range(rows)]

    # Perform dynamic programming to fill the dp table
    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                dp[i][j] = grid_values[i*cols+j][2]
                continue
            if i == 0:
                dp[i][j] = dp[i][j-1] + grid_values[i*cols+j][2]
            elif j == 0:
                dp[i][j] = dp[i-1][j] + grid_values[i*cols+j][2]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid_values[i*cols+j][2]

    # Determine the two paths that maximizer the sum of values
    path1_values = [0]
    path2_values = [0]

    i, j = rows-1, cols-1
    while (i, j) != (0, 0):
        path1_values.append(dp[i][j])
        path2_values.append(grid_values[i*cols+j][2])
        if dp[i-1][j] > dp[i][j-1]:
            i -= 1
        else:
            j -= 1

    path1_values.append(dp[i][j])
    path2_values.append(grid_values[i*cols+j][2])

    max_value = sum(path1_values) if sum(path1_values) > sum(path2_values) else sum(path2_values)

    return max_value
