def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0:
            grid[0][0] = value
        else:
            grid[x][y] += (grid[x - 1][y] if x > 0 else 0) + (grid[x][y - 1] if y > 0 else 0) + value

    left_max = 0
    for y in range(N):
        for x in range(N - 1, -1, -1):
            left_max = grid[x][y] if x == N - 1 else max(left_max, grid[x][y] + grid[x + 1][y])

    right_max = 0
    for y in range(N):
        for x in range(1, N):
            right_max = grid[x][y] if x == 0 else max(right_max, grid[x][y] + grid[x - 1][y])

    return max(left_max + grid[N - 1][N - 1], right_max + grid[0][0])
