        z = x
        x = y
        y = z

    while z < N:
        if x + y == N:
            if x == N:
                return f"{N}/{1}"
            else:
                return f"{x + 1}/{y - 1}"
        if x + y + factor == N:
            if x == N:
                return f"{N}/{factor}"
            else:
                return f"{x + 1}/{y - factor}"
        if y + factor * 2 == N:
            return f"{x + factor}/{y}"
        swap(x, y)
        factor *= 2
    return f"{x + factor}/{y}"
