    import string

    # Count the occurrences of each digit
    digit_count = {}
    for digit in num_str:
        if digit in digit_count:
            digit_count[digit] += 1
        else:
            digit_count[digit] = 1

    # Calculate the total number of pairs of digits
    total_pairs = sum(count // 2 for count in digit_count.values()) * 2

    # If there are not enough pairs of digits for K multiplication signs, return -1
    if K > total_pairs:
        return -1

    # Calculate the maximum product
    result = 1
    for i in range(K):
        max_digit = max(digit_count.keys())
        result *= max_digit ** 2
        digit_count[max_digit] -= 2

    return result
