def verify_isbn(isbn: str) -> str:
    if len(isbn) != 10 and len(isbn) != 13:
        raise ValueError("ISBN numbers can only be 10 or 13 characters long.")

    def calculate_check_digit(isbn: str) -> str:
        sum = 0
        if len(isbn) == 13:
            # Check for 'X' at the end
            if isbn[-1] == 'X':
                isbn = isbn[:-1] + '10'
        # Calculate checksum
        for i in range(1, len(isbn) + 1):
            if i % 2 == 1:
                sum += int(isbn[i - 1])
            else:
                sum += int(isbn[i - 1]) * 3
        return str((10 - sum % 10) % 10)

    if len(isbn) == 10:
        correct ISBN = isbn + calculate_check_digit(isbn)
        if correct ISBN == isbn:
            return "Right"
        else:
            return correct ISBN
    else:
        if calculate_check_digit(isbn) == isbn[-1]:
            return "Right"
        else:
            return isbn
