def verify_isbn(isbn: str) -> str:
    if len(isbn) != 13 and not isbn.endswith('X'):
        return f"Error: ISBN format is incorrect. Please provide a 13-digit ISBN."

    digits = list(isbn[:-1])
    # Replace 'X' with 10 for German ISBNs
    if isbn.endswith('X'):
        digits[-1] = '10'
    else:
        digits[-1] = isbn[-1]

    # Calculate the checksum
    checksum = 0
    for i, number in enumerate(digits):
        if i % 2 == 1:
            checksum += int(number) * 3
        else:
            checksum += int(number)

    # Compute the check digit
    check_digit = 11 - (checksum % 11)

    # Verify the checksum
    if check_digit == 10:
        check_digit = 'X'

    # Return the result
    if check_digit == isbn[-1]:
        return "Right"
    else:
        return isbn[:12] + check_digit if len(isbn) == 13 else isbn[:11] + check_digit
