def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    row_positions = [True for _ in range(M + 2)]
    col_positions = [True for _ in range(N + 2)]

    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        row_positions[Xi] = row_positions[Pi] = False
        col_positions[Yi] = col_positions[Qi] = False

    if not (K + L < M * N):
        return ('Error', 'Cannot add more aisles than classrooms')

    row_count = 0
    col_count = 0

    # Count the number of people that need to be separated by aisles
    for i in range(1, M + 1):
        for j in range(1, N + 1):
            if row_positions[i] and not col_positions[j]:
                row_count += 1
            elif not row_positions[i] and col_positions[j]:
                col_count += 1

    # Schedule aisles to minimize separation
    row_schedule = sorted([(row_count, row) for row in range(1, M + 1)])
    col_schedule = sorted([(col_count, col) for col in range(1, N + 1)])

    rowainsle = colainsle = None
    for pos, aisle in row_schedule:
        if not rowainsle:
            rowainsle = aisle
    for pos, aisle in col_schedule:
        if not colainsle:
            colainsle = aisle

    return f"{rowainsle} {colainsle}"
