def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    def count_chatting_pairs(position):
        chat_first, chat_second = position[0] < position[1], position[0] > position[1]
        count = 0
        for a, b in chatting_pairs:
            if chat_second == a < b or chat_first == a > b:
                count += 1
        return count

    def select_optimal_positions(chair_positions):
        max_pairs = -float('inf')
        optimal_positions = []

        for i in range(1, chair_positions - K - L + 2):
            for j in range(1, chair_positions - K - L + 2):
                if j != i and j > K and i > L:
                    chat_first, chat_second = i < j, i > j
                    pairs_count = count_chatting_pairs((i, j))
                    if pairs_count > max_pairs:
                        max_pairs = pairs_count
                        optimal_positions = [(i, j)]

        return optimal_positions

    chair_positions = sorted([x for x in range(M * N) if (x // M, x % M) not in chatting_pairs])
    optimal_positions = select_optimal_positions(len(chair_positions))

    if optimal_positions:
        row_index, col_index = optimal_positions[0]
        row_index = str(row_index // M)
        col_index = ' '.join(map(str, (col_index - K, col_index + 1)))
        return row_index, col_index
    else:
        return "No optimal positions found"
