    for i in range(n):
        DP[i][i] = 0

    # Fill DP table for 2 beads to n beads
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            head = beads[i]
            tail = beads[j]
            if head == tail:
                DP[i][j] =DP[i + 1][j - 1]
            else:
                for k in range(i + 1, j):
