from math import comb

def count_partitions(n: int, k: int, x: int) -> int:
    # Replace x* with n-x if x* > n to ensure each part is at least x
    if x * k > n:
        x = n // k

    # Calculate the number of partitions using the k-partitions formula
    # Please use comb function from math module which computes the binomial coefficient
    # The formula is used as follows:
    # count = sum(comb(n - k*part - 1, part - 1) for part in range(1, k + 1))
    # Calculate the Chinese Remainder Theorem (CRT) part to handle divisibility constraints
    def crt(a, b, c):
        return a * b * gcd(b, c) // gcd(a, b * c)

    def gcd(a, b):
        while b != 0:
            a, b = b, a % b
        return a

    # Calculate the number of valid partitions
    count = 0
    for part in range(1, k + 1):
        remainder = (n - k * part - 1) % (part - 1)
        if remainder % (part - 1) == 0:
            count += comb(n - k * part - 1, part - 1) // (part - 1)
        else:
            count += comb(n - k * part - 1, part - 1) // (part - 1) * crt(part - 1, 1, remainder // (part - 1))

    return count
