def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]

    if last == 0 or last > n // 2:
        memo[last] = 0
        return memo[last]

    sequence_count = 1  # Start with the current number 'n' itself
    previous_count = 0   # Initialize with the count for the previous number 'last'

    for i in range(1, n // 2 + 1):
        if i < last:
            sequence_count += count_sequences(n, i, memo)  # Recursively calculate for larger numbers
        previous_count += count_sequences(n, last, memo)  # Accumulate previous counts

    memo[last] = sequence_count + previous_count  # Store the result for future use
    return memo[last]
