def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    def bfs(start, end):
        queue = deque([(start, 0)])
        visited = {start}

        while queue:
            word, steps = queue.popleft()

            if word == end:
                return steps

            for rule in rules:
                if word.startswith(rule[0]):
                    new_word = word[:len(rule[0])] + rule[1] + word[len(rule[0]):]
                    if new_word not in visited:
                        visited.add(new_word)
                        queue.append((new_word, steps + 1))

        return "NO ANSWER!"

