def generate_numbers(n, rules) -> int:
    if n == 0: return 1

    queue = deque([n])
    visited = set()
    visited.add(n)

    count = 0

    while queue:
        current = queue.popleft()
        for x, y in rules:
            if current >= x:
                next_number = current - x
                if next_number == y and next_number not in visited:
                    visited.add(next_number)
                    count += 1
                elif next_number > y:
                    digits = next_number // 10
                    if (digits, y) in rules:
                        next_number += x
                        if next_number not in visited:
                            visited.add(next_number)
                            count += 1
        queue.append(current)

    return count
