def vigenere_decrypt(key, ciphertext):
    from string import ascii_lowercase

    def shift_char(char, shift):
        lower_id = ascii_lowercase.index(char)
        lower_id_shifted = (lower_id + shift) % 26
        return ascii_lowercase[lower_id_shifted]

    decrypted = []
    key_index = 0
    for char in ciphertext:
        shift = ascii_lowercase.index(key[key_index])
        if char in ascii_lowercase:
            decrypted.append(shift_char(char, -shift))
            key_index = (key_index + 1) % len(key)
        else:
            decrypted.append(char)
