def mod_inverse(a, b):
    if b == 0:
        return None

    gcd, x, y = extended_gcd(a, b)

    if gcd == 1:
        return x % b
    else:
        return None

def extended_gcd(a, b):
    if b == 0:
        return a, 1, 0

    gcd, s1, t1 = extended_gcd(b, a % b)
    s = t1 - (a // b) * s1
    t = s1
    return gcd, s, t
