def mod_inverse(a, b):
    if a == 0:
        return None

    r0, r1, s0, s1 = b, a, 0, 1

    while r1 != 0:
        q = r0 // r1
        r = r0 - q * r1
        s = s0 - q * s1
        r0, r1, s0, s1 = r1, r, s1, s

    if r0 != 1:
        return None

    if s0 < 0:
        return (s0 + b) % b
    return s0
```

