            j = len(perm) - 1
            while j > i:
                if perm[j] > perm[i - 1]:
                    perm[i - 1], perm[j] = perm[j], perm[i - 1]
                    break
            perm[i:] = sorted(perm[i:])
            return True
        i -= 1
    return False
```

