from typing import List

def minimum_students_to_leave(heights: List[int]) -> int:
    left, right = 0, len(heights) - 1
    result = 0

    while left < right:
        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1
            result += 1

    return result + 1
