def min_groups(w, n, prices):
    prices.sort()
    min_groups = 0
    total = 0

    for price in prices:
        if total + price <= w:
            total += price
        else:
            min_groups += 1
            total = price

    if total <= w:
        min_groups += 1

    return min_groups
