def min_groups(w, n, prices):
    if n == 0:
        return 0
    dp = [float('inf')] * (w + 1)
    for i in range(1, n + 1):
        for j in range(prices[i - 1], w + 1):
            dp[j] = min(dp[j], dp[j - prices[i - 1]] + 1)
    return dp[w]
```

