def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14
    else:
        # Iterate from n to 2 to compute the moves for each step
        moves = 2 + (2 * (n - 2)) * 2 - ((n - 1) * (n - 2))**2
        return moves
