        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14
    else:
        # Using the known recursive relation for double-disc Hanoi Towers
        # Total moves for n pairs of discs = 2**n - 3*(2**n - 1)
        # This is derived from the recursive relation for single-disc Hanoi problem^2 - 3*(^2 - 1)
        return 2**n - 3*(2**n - 1)
